def broadcast_shape(*shapes):
    if not shapes:
        return ()
    width = max(len(s) for s in shapes)
    padded = [(1,) * (width - len(s)) + tuple(s) for s in shapes]
    out = []
    for axis in range(width):
        sizes = {p[axis] for p in padded}
        sizes.discard(1)
        if len(sizes) > 1:
            raise ValueError(
                f"axis {axis - width}: incompatible sizes {sorted(sizes)}"
            )
        out.append(sizes.pop() if sizes else 1)
    return tuple(out)
